    lbl('D_m : 1 ≤ √m d(q) ≤ 2', cx + 150, cy + 175, C.mag, mq, 17, 'left');
    rect63(cx - 18, cy - 18, 36, 36, C.gold, q, 2.5); fillBox(cx - 18, cy - 18, 36, 36, C.gold, q * 0.35); lbl('Ξ_s(K)', cx, cy - 30, C.gold, q, 16);
    [0.4, 1.6, 2.7, 4.2, 5.4].forEach((an, i) => { const rx = 250 * Math.cos(an), ry = 125 * Math.sin(an), c = Math.cos(-0.3), s = Math.sin(-0.3); arrow(cx, cy, cx + rx * c - ry * s, cy + rx * s + ry * c, C.gold, mq * 0.8, 2); });
