    lbl('h_s = r_s s⁸ / a ≤ H s^(2/3) ,  s⁸ / h_s = a / r_s ;  K_rec = E⁻¹V compact', 530, 315, C.dim, q2, 14);
    const eq = Q(S, 1, 'tends to infinity exactly when the ground states converge', 0.6);
    chip(530, 395, 860, 62, 'r_s → ∞   ⇔   dist(F_s , e^(iθ)Φ_c) → 0', C.green, eq, 26);
