  lbl('β_s = ε s / d₀ ;  V_j ∘ σ = (−1)^j V_j ;  strip L = s^(−1/2)', 1395, 316, C.dim, eq, 15);
  const px = 1040, py = 780, pw = 680, ph = 380, [X, Y] = map110(px, py, pw, ph, -3.1, -1.2, -11.5, -5);
