    lbl('A₂ = ∫ r²|YΦ_c|² ,  J₂ = ∫ (V₂ + 2rV₁)|Φ_c|² ,  J_t = ∫ V_t |Φ_c|² > 0', 530, 420, C.dim, fq, 14);
    lbl('sample : ν = ε/d₀ = ' + S110.nu.toFixed(3) + ' ,  λ = ' + S110.lam.toFixed(2), 530, 455, C.dim, fq, 15);
